<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Arqueo sorpresivo</title><style>body{font-family:system-ui;background:#f4f7fb;color:#183453;padding:24px}main{max-width:900px;margin:auto;background:white;padding:26px;border-radius:14px}label{display:block;margin:12px 0}input,select,textarea{padding:9px;border:1px solid #bbc9d8;border-radius:6px}input[type=number]{width:110px}.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:20px}.fila{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #edf0f4;padding:5px}button{padding:12px 20px;background:#145ba1;color:white;border:0;border-radius:7px;cursor:pointer}.error{color:#b32323}</style></head><body><main><p><a href="{{ route($ruta.'.sorpresivos.index') }}">← Arqueos sorpresivos</a></p><h1>Nuevo arqueo sorpresivo</h1><p>El supervisor realiza el conteo junto al receptor. El registro queda pendiente de la confirmación electrónica del receptor.</p>@if($errors->any())<div class="error"><ul>@foreach($errors->all() as $e)<li>{{ $e }}</li>@endforeach</ul></div>@endif<form method="post" action="{{ route($ruta.'.sorpresivos.store') }}">@csrf<label>Receptor, agencia y ventanilla<br><select name="jornada_id" required><option value="">Seleccione un turno de hoy</option>@foreach($jornadas as $j)<option value="{{ $j->id }}" @selected(old('jornada_id')==$j->id)>{{ $j->agencia->nombre }} · {{ $j->ventanilla->codigo }} · {{ $j->receptor->nombre_completo }} · {{ $j->turno->nombre }}</option>@endforeach</select></label><div class="cols"><section><h2>Billetes</h2>@foreach($billetes as $v)<div class="fila"><label for="b{{ $v }}">Q {{ $v }}</label><input id="b{{ $v }}" type="number" min="0" max="10000000" name="billetes[{{ $v }}]" value="{{ old('billetes.'.$v,0) }}" required></div>@endforeach</section><section><h2>Monedas</h2>@foreach($monedas as $v)<div class="fila"><label for="m{{ str_replace('.','',$v) }}">Q {{ $v }}</label><input id="m{{ str_replace('.','',$v) }}" type="number" min="0" max="10000000" name="monedas[{{ $v }}]" value="{{ old('monedas.'.$v,0) }}" required></div>@endforeach</section></div><label>Corte del sistema bancario (Q)<br><input type="number" step="0.01" min="0" name="total_corte" value="{{ old('total_corte','0.00') }}" required></label><label>Justificación de diferencia (obligatoria si hay faltante o sobrante)<br><textarea name="justificacion_diferencia" rows="3" style="width:95%">{{ old('justificacion_diferencia') }}</textarea></label><label>Observaciones<br><textarea name="observaciones" rows="3" style="width:95%">{{ old('observaciones') }}</textarea></label><label><input type="checkbox" name="confirmar" value="1" required> Confirmo que el conteo fue realizado y que deseo firmar el registro como supervisor.</label><button type="submit">Registrar y firmar arqueo sorpresivo</button></form></main></body></html>